532	/// This is only executed the first time an element is visited.
533	fn prepare(
534	    engine: &mut Engine,
535	    locator: &mut SplitLocator,
536	    elem: &mut Content,
537	    map: &mut Styles,
538	    styles: StyleChain,
539	) -> SourceResult<Option<(Tag, Tag)>> {
540	    // Generate a location for the element, which uniquely identifies it in
541	    // the document. This has some overhead, so we only do it for elements
542	    // that are explicitly marked as locatable and labelled elements.
543	    //
544	    // The element could already have a location even if it is not prepared
545	    // when it stems from a query.
546	    let key = typst_utils::hash128(&elem);
547	    let flags = TagFlags {
548	        introspectable: elem.is_locatable()
549	            || elem.label().is_some()
550	            || elem.location().is_some(),
551	        tagged: elem.is_tagged(),
552	    };
553	    if elem.location().is_none() && flags.any() {
554	        let loc = locator.next_location(engine, key, elem.span());
555	        elem.set_location(loc);
556	    }
557	
558	    // Apply built-in show-set rules. User-defined show-set rules are already
559	    // considered in the map built while determining the verdict.
560	    if let Some(show_settable) = elem.with::<dyn ShowSet>() {
561	        map.apply(show_settable.show_set(styles));
562	    }
563	
564	    // If necessary, generated "synthesized" fields (which are derived from
565	    // other fields or queries). Do this after show-set so that show-set styles
566	    // are respected.
567	    if let Some(synthesizable) = elem.with_mut::<dyn Synthesize>() {
568	        synthesizable.synthesize(engine, styles.chain(map))?;
569	    }
570	
571	    // Copy style chain fields into the element itself, so that they are
572	    // available in rules.
573	    elem.materialize(styles.chain(map));
574	
575	    // If the element is locatable, create start and end tags to be able to find
576	    // the element in the frames after layout. Do this after synthesis and
577	    // materialization, so that it includes the synthesized fields. Do it before
578	    // marking as prepared so that show-set rules will apply to this element
579	    // when queried.
580	    let tags = elem
581	        .location()
582	        .map(|loc| (Tag::Start(elem.clone(), flags), Tag::End(loc, key, flags)));
583	
584	    // Ensure that this preparation only runs once by marking the element as
585	    // prepared.
586	    elem.mark_prepared();
587	
588	    Ok(tags)
589	}
