591	/// Handles a styled element.
592	fn visit_styled<'a>(
593	    s: &mut State<'a, '_, '_, '_>,
594	    content: &'a Content,
595	    mut local: Cow<'a, Styles>,
596	    outer: StyleChain<'a>,
597	) -> SourceResult<()> {
598	    // Nothing to do if the styles are actually empty.
599	    if local.is_empty() {
600	        return visit(s, content, outer);
601	    }
602	
603	    // Check for document and page styles.
604	    let mut pagebreak = false;
605	    for style in local.iter() {
606	        let Some(elem) = style.element() else { continue };
607	        if elem == DocumentElem::ELEM {
608	            let local = StyleChain::new(&local);
609	            if let RealizationKind::Document { info } = &mut s.kind {
610	                info.populate(local);
611	            } else if !matches!(s.kind, RealizationKind::Bundle) {
612	                bail!(
613	                    style.span(),
614	                    "document set rules are not allowed inside of containers",
615	                );
616	            }
617	            if local.has(DocumentElem::format)
618	                && !matches!(s.kind, RealizationKind::Bundle)
619	            {
620	                bail!(
621	                    style.span(),
622	                    "setting the document format is only supported in the bundle target"
623	                );
624	            }
625	        } else if elem == TextElem::ELEM {
626	            // Infer the document locale from the first toplevel set rule.
627	            if let RealizationKind::Document { info } = &mut s.kind {
628	                info.populate_locale(StyleChain::new(&local));
629	            }
630	        } else if elem == PageElem::ELEM {
631	            match s.kind {
632	                RealizationKind::Bundle => {}
633	                RealizationKind::Document { .. } => match outer.get(TargetElem::target) {
634	                    Target::Paged => {
635	                        // When there are page styles, we "break free" from our show
636	                        // rule cage.
637	                        pagebreak = true;
638	                        s.outside = true;
639	                    }
640	                    Target::Html => {
641	                        s.engine.sink.warn(warning!(
642	                            style.span(),
643	                            "page set rule was ignored during HTML export"
644	                        ));
645	                    }
646	                    Target::Bundle => {}
647	                },
648	                _ => bail!(
649	                    style.span(),
650	                    "page configuration is not allowed inside of containers",
651	                ),
652	            }
653	        }
654	    }
655	
656	    // If we are not within a container or show rule, mark the styles as
657	    // "outside". This will allow them to be lifted to the page level.
658	    if s.outside {
659	        local = Cow::Owned(local.into_owned().outside());
660	    }
661	
662	    // Lifetime-extend the styles if necessary.
663	    let outer = s.arenas.bump.alloc(outer);
664	    let local = match local {
665	        Cow::Borrowed(map) => map,
666	        Cow::Owned(owned) => &*s.arenas.styles.alloc(owned),
667	    };
668	
669	    // Generate a weak pagebreak if there is a page interruption. For the
670	    // starting pagebreak we only want the styles before and including the
671	    // interruptions, not trailing styles that happen to be in the same `Styles`
672	    // list, so we trim the local styles.
673	    if pagebreak {
674	        let relevant = local
675	            .as_slice()
676	            .trim_end_matches(|style| style.element() != Some(PageElem::ELEM));
677	        visit(s, PagebreakElem::shared_weak(), outer.chain(relevant))?;
678	    }
679	
680	    finish_interrupted(s, local)?;
681	    visit(s, content, outer.chain(local))?;
682	    finish_interrupted(s, local)?;
683	
684	    // Generate a weak "boundary" pagebreak at the end. In comparison to a
685	    // normal weak pagebreak, the styles of this are ignored during layout, so
686	    // it doesn't really matter what we use here.
687	    if pagebreak {
688	        visit(s, PagebreakElem::shared_boundary(), *outer)?;
689	    }
690	
691	    Ok(())
692	}
