812	/// Finishes groupings while any active group is interrupted by the styles.
813	fn finish_interrupted(s: &mut State, local: &Styles) -> SourceResult<()> {
814	    let mut last = None;
815	    for elem in local.iter().filter_map(|style| style.element()) {
816	        if last == Some(elem) {
817	            continue;
818	        }
819	        finish_grouping_while(s, |s| {
820	            s.groupings.iter().any(|grouping| (grouping.rule.interrupt)(elem))
821	                && if is_fully_inline_or_neutral(s) {
822	                    s.groupings[0].interrupted = true;
823	                    false
824	                } else {
825	                    true
826	                }
827	        })?;
828	        last = Some(elem);
829	    }
830	    Ok(())
831	}
832	
833	/// Finishes groupings while `f` returns `true`.
834	fn finish_grouping_while<F>(s: &mut State, mut f: F) -> SourceResult<()>
835	where
836	    F: FnMut(&mut State) -> bool,
837	{
838	    // Finishing of a group may result in new content and new grouping. This
839	    // can, in theory, go on for a bit. To prevent it from becoming an infinite
840	    // loop, we keep track of the iteration count.
841	    let mut i = 0;
842	    while f(s) {
843	        finish_innermost_grouping(s)?;
844	        i += 1;
845	        if i > 512 {
846	            bail!(Span::detached(), "maximum grouping depth exceeded");
847	        }
848	    }
849	    Ok(())
850	}
851	
852	/// Finishes the currently innermost grouping.
853	fn finish_innermost_grouping(s: &mut State) -> SourceResult<()> {
854	    // The grouping we are interrupting.
855	    let Grouping { start, rule, contains_neutral, .. } = s.groupings.pop().unwrap();
856	    if contains_neutral {
857	        // If the grouping collected neutral elements, we segment them out and
858	        // then finish the individual subgroups separately.
859	        let elems = s.store_slice(&s.sink[start..]);
860	        s.sink.truncate(start);
861	        for (is_neutral, slice) in
862	            elems.group_by_key(|(c, _)| (rule.effect)(c) == GroupingEffect::Neutral)
863	        {
864	            if is_neutral {
865	                for &(content, styles) in slice {
866	                    visit(s, content, styles)?;
867	                }
868	            } else {
869	                // Trim and revisit leading non-trigger elements.
870	                // `finish_grouping` only takes care of trimming trailing
871	                // elements as usually a grouping cannot start without a trigger
872	                // element.
873	                let trimmed = slice.trim_start_matches(|(c, _)| {
874	                    (rule.effect)(c) != GroupingEffect::Trigger
875	                });
876	                let split = slice.len() - trimmed.len();
877	                for &(content, styles) in &slice[..split] {
878	                    visit(s, content, styles)?;
879	                }
880	
881	                // If we only had inner elements and tags, don't finish the
882	                // group at all.
883	                if !trimmed.is_empty() {
884	                    let start = s.sink.len();
885	                    s.sink.extend_from_slice(trimmed);
886	                    finish_grouping(s, rule, start)?;
887	                }
888	            }
889	        }
890	        Ok(())
891	    } else {
892	        finish_grouping(s, rule, start)
893	    }
894	}
